knzlysyhnp8xdnkdpw1mko2t	hero	{"title":"Luxury Towels & Blankets","titleHighlight":"with Your Name","subtitle":"Premium quality embroidered products, personalised with love. The perfect gift for your little ones and loved ones.","primaryButtonText":"Shop Now","primaryButtonLink":"/shop","secondaryButtonText":"Couple Sets","secondaryButtonLink":"/shop?filter=couples","imageUrl":""}
ygerxandrz4sit9klklnylnm	homepageCollections	{"sections":[{"id":"collections","label":"Collections","heading":"Shop by Collection","cards":[{"title":"For Kids","description":"Make bath time their favourite time. Our kids' collection features Disney princesses, superheroes, unicorns and more — all embroidered with your child's name. Towels and blankets they'll never want to let go of.","link":"/shop?filter=kids","imageUrl":""},{"title":"For Adults","description":"Elevate your everyday essentials. Our adults' range features elegant monograms, laurel crests and classic initials — personalised towels and blankets that bring a touch of luxury to your home.","link":"/shop?filter=adults","imageUrl":""},{"title":"For Couples","description":"The perfect his & hers gift. Our couple towel sets come with matching embroidered designs — from King & Queen crowns to Mr. Right & Mrs. Always Right. Ideal for weddings, anniversaries and housewarmings.","link":"/shop?filter=couples","imageUrl":""}]},{"id":"productTypes","label":"Products","heading":"Shop by Product","cards":[{"title":"Towels","description":"Wrap yourself in luxury. Our 550 GSM zero-twist cotton towels are soft, absorbent and beautifully embroidered with your name or initials. Available for kids and adults in a range of fun and elegant designs.","link":"/shop","imageUrl":""},{"title":"Bathrobes","description":"Step out of the shower in style. Our plush terry cotton bathrobes are personalised with custom embroidery, making every day feel like a spa day. Perfect as a gift or a treat for yourself.","link":"/shop","imageUrl":""},{"title":"Blankets","description":"Snuggle up with a blanket made just for you. Our ultra-soft AC blankets come with beautiful embroidered names and fun designs — loved by kids and perfect for gifting on birthdays and special occasions.","link":"/shop","imageUrl":""}]}],"deletedHistory":[{"id":"section_1770771485817_88wji","label":"","heading":"Test Section","cards":[{"title":"Test Card","description":"","link":"/shop","imageUrl":""}]}]}
